			assertTrue(pullEntered.await(10, TimeUnit.SECONDS), "the source pull must already be active");
			limited.interrupt();
			assertTrue(taskQueued.await(10, TimeUnit.SECONDS), "timeout delivery must be queued before close");
			workers.submit(limited::close).get(10, TimeUnit.SECONDS);
			assertEquals(1, releasePull.getCount(), "close returns while the source pull remains held");
			assertEquals(0, closes.get(), "the active source remains owned at delivery");
			Runnable delivery = queued.getAndSet(null);
